#!/bin/sh
# Hand the approved queue to the press dispatcher.
echo "enqueue press queue at $(date -u +%Y-%m-%dT%H:%M:%SZ)" >> .effects.log

arguments.command:
python3 - <<'PY'
import re
for s in ['４１８','۴۱۸','٤١٨','418','４０２','۴۰۲','٤٠٢']:
    m=re.fullmatch(r'\d+',s)
    print(repr(s), bool(m), end=' ')
    if m:
        try:
            print(int(s), end=' ')
        except Exception as e:
            print('int err',e,end=' ')
    print()
print(sorted([418,402]))
PY
